final_template:
AWSTemplateFormatVersion: "2010-09-09"
Description: >
  Cedar-based access control for a bookstore application implemented with Amazon
  Verified Permissions. Creates a policy store with a strict Bookstore schema
  (Role, User, Book entities; View and ViewWithPremiumOffers actions with a
  region request context) plus a set of static Cedar policies, and publishes the
  policy store identifier to AWS Systems Manager Parameter Store.

Resources:

  BookstorePolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    Properties:
      Description: Verified Permissions policy store for the bookstore application
      ValidationSettings:
        Mode: STRICT
      Schema:
        CedarJson: |
          {
            "Bookstore": {
              "entityTypes": {
                "User": {
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "yearsAsMember": {
                        "type": "Long"
                      }
                    }
                  },
                  "memberOfTypes": [
                    "Role"
                  ]
                },
                "Role": {},
                "Book": {
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "owner": {
                        "type": "Entity",
                        "name": "User"
                      }
                    }
                  }
                }
              },
              "actions": {
                "View": {
                  "appliesTo": {
                    "principalTypes": [
                      "User"
                    ],
                    "resourceTypes": [
                      "Book"
                    ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String"
                        }
                      }
                    }
                  }
                },
                "ViewWithPremiumOffers": {
                  "appliesTo": {
                    "principalTypes": [
                      "User"
                    ],
                    "resourceTypes": [
                      "Book"
                    ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String"
                        }
                      }
                    }
                  }
                }
              }
            }
          }

  AdminViewAnyBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit users in the Admin role to view any book.
          Statement: |
            permit (
              principal in Bookstore::Role::"Admin",
              action == Bookstore::Action::"View",
              resource
            );

  ForbidSuperAdminViewBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Forbid the named administrator from viewing any book.
          Statement: |
            forbid (
              principal == Bookstore::User::"admin-super",
              action == Bookstore::Action::"View",
              resource
            );

  PublisherViewOwnedBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit users in the Publisher role to view only the books they own.
          Statement: |
            permit (
              principal in Bookstore::Role::"Publisher",
              action == Bookstore::Action::"View",
              resource
            )
            when {
              resource.owner == principal
            };

  AliceViewSpecificBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit the named user to view one specific named book.
          Statement: |
            permit (
              principal == Bookstore::User::"alice",
              action == Bookstore::Action::"View",
              resource == Bookstore::Book::"book-001"
            );

  CustomerPremiumOffersTwoYearsPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit customers with two or more years of membership to view premium offers.
          Statement: |
            permit (
              principal in Bookstore::Role::"Customer",
              action == Bookstore::Action::"ViewWithPremiumOffers",
              resource
            )
            when {
              principal.yearsAsMember >= 2
            };

  ForbidCustomerPremiumOffersUnderTwoYearsPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Forbid customers with less than two years of membership from viewing premium offers.
          Statement: |
            forbid (
              principal in Bookstore::Role::"Customer",
              action == Bookstore::Action::"ViewWithPremiumOffers",
              resource
            )
            when {
              principal.yearsAsMember < 2
            };

  ForbidNonUsRegionPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Forbid View and ViewWithPremiumOffers when the request context region is not the United States.
          Statement: |
            forbid (
              principal,
              action in [
                Bookstore::Action::"View",
                Bookstore::Action::"ViewWithPremiumOffers"
              ],
              resource
            )
            when {
              context.region != "US"
            };

  PolicyStoreIdParameter:
    Type: AWS::SSM::Parameter
    Properties:
      Name: /bookstore/verified-permissions/policy-store-id
      Description: Identifier of the bookstore Verified Permissions policy store
      Type: String
      Value: !Ref BookstorePolicyStore

Outputs:
  PolicyStoreId:
    Description: Identifier of the bookstore Verified Permissions policy store
    Value: !Ref BookstorePolicyStore
  PolicyStoreArn:
    Description: ARN of the bookstore Verified Permissions policy store
    Value: !GetAtt BookstorePolicyStore.Arn
  PolicyStoreIdParameterName:
    Description: Name of the SSM parameter holding the policy store identifier
    Value: !Ref PolicyStoreIdParameter

AWSTemplateFormatVersion: '2010-09-09'
Description: TodoAPIwithJs - self-contained AWS AppSync GraphQL API with API key authentication, DynamoDB table with an owner GSI, JavaScript (APPSYNC_JS) pipeline resolvers for CRUD and by-owner queries, and real-time subscriptions.

Resources:

  TodosTable:
    Type: AWS::DynamoDB::Table
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: owner-index
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL
      PointInTimeRecoverySpecification:
        PointInTimeRecoveryEnabled: true
      SSESpecification:
        SSEEnabled: true

  AppSyncDynamoDBRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: AppSyncTodosTableAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                Resource:
                  - !GetAtt TodosTable.Arn
                  - !Sub '${TodosTable.Arn}/index/*'

  TodoAPI:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: TodoAPIwithJs
      AuthenticationType: API_KEY
      XrayEnabled: true

  TodoApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt TodoAPI.ApiId
      Description: API key for the TodoAPIwithJs GraphQL API

  TodoAPISchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt TodoAPI.ApiId
      Definition: |
        schema {
          query: Query
          mutation: Mutation
          subscription: Subscription
        }

        type Todo {
          id: ID!
          name: String!
          description: String
          owner: String
          createdAt: AWSDateTime
          updatedAt: AWSDateTime
        }

        input CreateTodoInput {
          id: ID
          name: String!
          description: String
          owner: String
        }

        input UpdateTodoInput {
          id: ID!
          name: String
          description: String
          owner: String
        }

        input DeleteTodoInput {
          id: ID!
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos: [Todo]
          queryTodosByOwner(owner: String!): [Todo]
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(input: DeleteTodoInput!): Todo
        }

        type Subscription {
          onCreateTodo: Todo
            @aws_subscribe(mutations: ["createTodo"])
          onUpdateTodo: Todo
            @aws_subscribe(mutations: ["updateTodo"])
          onDeleteTodo: Todo
            @aws_subscribe(mutations: ["deleteTodo"])
        }

  TodosDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt TodoAPI.ApiId
      Name: TodosTableDataSource
      Description: DynamoDB data source for the Todos table
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncDynamoDBRole.Arn
      DynamoDBConfig:
        TableName: !Ref TodosTable
        AwsRegion: !Ref AWS::Region

  CreateTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoAPI.ApiId
      Name: createTodo
      Description: Creates a Todo item in DynamoDB
      DataSourceName: !GetAtt TodosDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const now = util.time.nowISO8601();
          const id = input.id ? input.id : util.autoId();
          const item = {
            id: id,
            name: input.name,
            owner: input.owner ? input.owner : 'unknown',
            createdAt: now,
            updatedAt: now,
          };
          if (input.description !== undefined && input.description !== null) {
            item.description = input.description;
          }
          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id: id }),
            attributeValues: util.dynamodb.toMapValues(item),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  UpdateTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoAPI.ApiId
      Name: updateTodo
      Description: Updates an existing Todo item in DynamoDB
      DataSourceName: !GetAtt TodosDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const names = {};
          const values = {};
          const sets = [];

          if (input.name !== undefined && input.name !== null) {
            names['#name'] = 'name';
            values[':name'] = input.name;
            sets.push('#name = :name');
          }
          if (input.description !== undefined && input.description !== null) {
            names['#description'] = 'description';
            values[':description'] = input.description;
            sets.push('#description = :description');
          }
          if (input.owner !== undefined && input.owner !== null) {
            names['#owner'] = 'owner';
            values[':owner'] = input.owner;
            sets.push('#owner = :owner');
          }

          names['#updatedAt'] = 'updatedAt';
          values[':updatedAt'] = util.time.nowISO8601();
          sets.push('#updatedAt = :updatedAt');

          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id: input.id }),
            update: {
              expression: 'SET ' + sets.join(', '),
              expressionNames: names,
              expressionValues: util.dynamodb.toMapValues(values),
            },
            condition: {
              expression: 'attribute_exists(#id)',
              expressionNames: { '#id': 'id' },
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  DeleteTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoAPI.ApiId
      Name: deleteTodo
      Description: Deletes a Todo item from DynamoDB
      DataSourceName: !GetAtt TodosDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.input.id }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  GetTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoAPI.ApiId
      Name: getTodo
      Description: Retrieves a single Todo item from DynamoDB
      DataSourceName: !GetAtt TodosDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  ListTodosFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoAPI.ApiId
      Name: listTodos
      Description: Lists Todo items from DynamoDB
      DataSourceName: !GetAtt TodosDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'Scan',
            limit: 100,
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result.items;
        }

  QueryTodosByOwnerFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoAPI.ApiId
      Name: queryTodosByOwner
      Description: Queries Todo items by owner using the owner-index GSI
      DataSourceName: !GetAtt TodosDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'Query',
            index: 'owner-index',
            query: {
              expression: '#owner = :owner',
              expressionNames: { '#owner': 'owner' },
              expressionValues: util.dynamodb.toMapValues({ ':owner': ctx.args.owner }),
            },
            limit: 100,
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result.items;
        }

  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoAPISchema
    Properties:
      ApiId: !GetAtt TodoAPI.ApiId
      TypeName: Mutation
      FieldName: createTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          if (!input || !input.name) {
            util.error('createTodo requires the input.name field', 'ValidationError');
          }
          return {};
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt CreateTodoFunction.FunctionId

  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoAPISchema
    Properties:
      ApiId: !GetAtt TodoAPI.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          if (!input || !input.id) {
            util.error('updateTodo requires the input.id field', 'ValidationError');
          }
          return {};
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt UpdateTodoFunction.FunctionId

  DeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoAPISchema
    Properties:
      ApiId: !GetAtt TodoAPI.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          if (!input || !input.id) {
            util.error('deleteTodo requires the input.id field', 'ValidationError');
          }
          return {};
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt DeleteTodoFunction.FunctionId

  GetTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoAPISchema
    Properties:
      ApiId: !GetAtt TodoAPI.ApiId
      TypeName: Query
      FieldName: getTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          if (!ctx.args.id) {
            util.error('getTodo requires an id argument', 'ValidationError');
          }
          return {};
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt GetTodoFunction.FunctionId

  ListTodosResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoAPISchema
    Properties:
      ApiId: !GetAtt TodoAPI.ApiId
      TypeName: Query
      FieldName: listTodos
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt ListTodosFunction.FunctionId

  QueryTodosByOwnerResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoAPISchema
    Properties:
      ApiId: !GetAtt TodoAPI.ApiId
      TypeName: Query
      FieldName: queryTodosByOwner
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          if (!ctx.args.owner) {
            util.error('queryTodosByOwner requires an owner argument', 'ValidationError');
          }
          return {};
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt QueryTodosByOwnerFunction.FunctionId

Outputs:
  GraphQLApiId:
    Description: AppSync GraphQL API ID
    Value: !GetAtt TodoAPI.ApiId
  GraphQLApiUrl:
    Description: AppSync GraphQL API endpoint URL
    Value: !GetAtt TodoAPI.GraphQLUrl
  ApiKey:
    Description: API key for the TodoAPIwithJs GraphQL API
    Value: !GetAtt TodoApiKey.ApiKey
  DynamoDBTableName:
    Description: Name of the DynamoDB table backing the API
    Value: !Ref TodosTable
  DynamoDBTableArn:
    Description: ARN of the DynamoDB table backing the API
    Value: !GetAtt TodosTable.Arn

AWSTemplateFormatVersion: '2010-09-09'
Description: >-
  SimpleTodoAPI - AWS AppSync GraphQL API that uses JavaScript resolvers and API key
  authentication, backed by a single DynamoDB table with an owner secondary index.

Resources:

  # ---------------------------------------------------------------------------
  # DynamoDB table that stores the to-do items
  # ---------------------------------------------------------------------------
  TodoTable:
    Type: AWS::DynamoDB::Table
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: owner-index
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL
      SSESpecification:
        SSEEnabled: true
      PointInTimeRecoverySpecification:
        PointInTimeRecoveryEnabled: true

  # ---------------------------------------------------------------------------
  # Service role that AppSync assumes to read and write the to-do table
  # ---------------------------------------------------------------------------
  AppSyncDynamoDBRole:
    Type: AWS::IAM::Role
    Properties:
      Description: Service role that AWS AppSync assumes to read and write the to-do table
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: TodoTableAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:BatchGetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                  - dynamodb:ConditionCheckItem
                  - dynamodb:DescribeTable
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub '${TodoTable.Arn}/index/*'

  # ---------------------------------------------------------------------------
  # Service role that AppSync assumes to publish resolver logs to CloudWatch Logs
  # ---------------------------------------------------------------------------
  AppSyncCloudWatchLogsRole:
    Type: AWS::IAM::Role
    Properties:
      Description: Service role that AWS AppSync assumes to write resolver logs to CloudWatch Logs
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      ManagedPolicyArns:
        - !Sub 'arn:${AWS::Partition}:iam::aws:policy/service-role/AWSAppSyncPushToCloudWatchLogs'

  # ---------------------------------------------------------------------------
  # GraphQL API with API key authentication
  # ---------------------------------------------------------------------------
  SimpleTodoAPI:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: SimpleTodoAPI
      AuthenticationType: API_KEY
      XrayEnabled: true
      LogConfig:
        CloudWatchLogsRoleArn: !GetAtt AppSyncCloudWatchLogsRole.Arn
        FieldLogLevel: ERROR

  SimpleTodoApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      Description: API key used to authenticate requests to SimpleTodoAPI

  # ---------------------------------------------------------------------------
  # Single DynamoDB data source shared by all six resolvers
  # ---------------------------------------------------------------------------
  TodoDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      Name: TodoTableDataSource
      Description: DynamoDB data source for the to-do table
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncDynamoDBRole.Arn
      DynamoDBConfig:
        TableName: !Ref TodoTable
        AwsRegion: !Ref AWS::Region
        UseCallerCredentials: false

  # ---------------------------------------------------------------------------
  # GraphQL schema
  # ---------------------------------------------------------------------------
  TodoGraphQLSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      Definition: |
        enum TodoStatus {
          PENDING
          IN_PROGRESS
          COMPLETED
        }

        type Todo {
          id: ID!
          title: String
          description: String
          status: TodoStatus
          priority: Int
          owner: String
          createdAt: AWSDateTime
          updatedAt: AWSDateTime
        }

        type TodoConnection {
          items: [Todo]
          nextToken: String
        }

        input CreateTodoInput {
          id: ID
          title: String!
          description: String
          status: TodoStatus
          priority: Int
          owner: String!
        }

        input UpdateTodoInput {
          id: ID!
          title: String
          description: String
          status: TodoStatus
          priority: Int
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos(limit: Int, nextToken: String): TodoConnection
          todosByOwner(owner: String!, limit: Int, nextToken: String): TodoConnection
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(id: ID!): Todo
        }

  # ---------------------------------------------------------------------------
  # Mutation: createTodo
  # ---------------------------------------------------------------------------
  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Mutation
      FieldName: createTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const now = util.time.nowISO8601();

          const item = {
            id: input.id ? input.id : util.autoId(),
            title: input.title,
            owner: input.owner,
            priority: input.priority !== undefined && input.priority !== null ? input.priority : 0,
            createdAt: now,
            updatedAt: now,
          };

          if (input.description !== undefined && input.description !== null) {
            item.description = input.description;
          }

          if (input.status !== undefined && input.status !== null) {
            item.status = input.status;
          }

          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id: item.id }),
            attributeValues: util.dynamodb.toMapValues(item),
            condition: {
              expression: 'attribute_not_exists(#id)',
              expressionNames: { '#id': 'id' },
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  # ---------------------------------------------------------------------------
  # Mutation: updateTodo
  # ---------------------------------------------------------------------------
  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const now = util.time.nowISO8601();

          const expressionNames = { '#updatedAt': 'updatedAt' };
          const expressionValues = { ':updatedAt': now };
          const setExpressions = ['#updatedAt = :updatedAt'];
          const removeExpressions = [];

          const fields = ['title', 'description', 'status', 'priority', 'owner'];

          for (const field of fields) {
            if (!(field in input)) {
              continue;
            }

            const nameKey = '#' + field;
            expressionNames[nameKey] = field;

            if (input[field] === null || input[field] === undefined) {
              removeExpressions.push(nameKey);
            } else {
              const valueKey = ':' + field;
              expressionValues[valueKey] = input[field];
              setExpressions.push(nameKey + ' = ' + valueKey);
            }
          }

          let expression = 'SET ' + setExpressions.join(', ');
          if (removeExpressions.length > 0) {
            expression += ' REMOVE ' + removeExpressions.join(', ');
          }

          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id: input.id }),
            update: {
              expression: expression,
              expressionNames: expressionNames,
              expressionValues: util.dynamodb.toMapValues(expressionValues),
            },
            condition: {
              expression: 'attribute_exists(#id)',
              expressionNames: { '#id': 'id' },
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  # ---------------------------------------------------------------------------
  # Mutation: deleteTodo
  # ---------------------------------------------------------------------------
  DeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
            condition: {
              expression: 'attribute_exists(#id)',
              expressionNames: { '#id': 'id' },
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }

          const result = ctx.result ? ctx.result : {};
          const id = result.id ? result.id : ctx.args.id;

          return {
            id: id,
            title: result.title,
            description: result.description,
            status: result.status,
            priority: result.priority,
            owner: result.owner,
            createdAt: result.createdAt,
            updatedAt: result.updatedAt,
          };
        }

  # ---------------------------------------------------------------------------
  # Query: getTodo
  # ---------------------------------------------------------------------------
  GetTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Query
      FieldName: getTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
            consistentRead: true,
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  # ---------------------------------------------------------------------------
  # Query: listTodos
  # ---------------------------------------------------------------------------
  ListTodosResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Query
      FieldName: listTodos
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const request = {
            operation: 'Scan',
            limit: ctx.args.limit ? ctx.args.limit : 20,
          };

          if (ctx.args.nextToken) {
            request.nextToken = ctx.args.nextToken;
          }

          return request;
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }

          return {
            items: ctx.result.items ? ctx.result.items : [],
            nextToken: ctx.result.nextToken,
          };
        }

  # ---------------------------------------------------------------------------
  # Query: todosByOwner (uses the owner-index secondary index)
  # ---------------------------------------------------------------------------
  TodosByOwnerResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Query
      FieldName: todosByOwner
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const request = {
            operation: 'Query',
            index: 'owner-index',
            query: util.dynamodb.toMapValues({ owner: ctx.args.owner }),
            scanIndexForward: true,
            limit: ctx.args.limit ? ctx.args.limit : 20,
          };

          if (ctx.args.nextToken) {
            request.nextToken = ctx.args.nextToken;
          }

          return request;
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }

          return {
            items: ctx.result.items ? ctx.result.items : [],
            nextToken: ctx.result.nextToken,
          };
        }

Outputs:
  GraphQLApiId:
    Description: Identifier of the AppSync GraphQL API
    Value: !GetAtt SimpleTodoAPI.ApiId

  GraphQLApiUrl:
    Description: HTTPS endpoint of the AppSync GraphQL API
    Value: !GetAtt SimpleTodoAPI.GraphQLUrl

  ApiKeyId:
    Description: Identifier of the API key created for testing SimpleTodoAPI
    Value: !Ref SimpleTodoApiKey

  TodoTableName:
    Description: Name of the DynamoDB table that stores the to-do items
    Value: !Ref TodoTable
